        }
        return {-1, -1};
    }
};

class Solution {
    public int[] findIndices(int[] nums, int indexDifference, int valueDifference) {
        int minI = 0, maxI = 0;
        for (int j = indexDifference; j < nums.length; j++) {
            int i = j - indexDifference;
            if (nums[i] < nums[minI]) minI = i;
            if (nums[i] > nums[maxI]) maxI = i;
            if (Math.abs(nums[j] - nums[minI]) >= valueDifference) return new int[]{minI, j};
            if (Math.abs(nums[j] - nums[maxI]) >= valueDifference) return new int[]{maxI, j};
        }
        return new int[]{-1, -1};
    }
}

/**
 * @param {number[]} nums
 * @param {number} indexDifference
 * @param {number} valueDifference
 * @return {number[]}
 */
var findIndices = function(nums, indexDifference, valueDifference) {
    let minI = 0, maxI = 0;
    for (let j = indexDifference; j < nums.length; j++) {
        const i = j - indexDifference;
        if (nums[i] < nums[minI]) minI = i;
        if (nums[i] > nums[maxI]) maxI = i;
        if (Math.abs(nums[j] - nums[minI]) >= valueDifference) return [minI, j];
        if (Math.abs(nums[j] - nums[maxI]) >= valueDifference) return [maxI, j];
    }
    return [-1, -1];
};
